$jobs=$pdo->query("SELECT j.id,j.campaign_id FROM sms_jobs j JOIN campaigns c ON c.id=j.campaign_id WHERE j.status='queued' AND c.test_mode=1 LIMIT 200")->fetchAll();foreach($jobs as $j){$pdo->prepare("UPDATE sms_jobs SET status='sent',updated_at=NOW() WHERE id=? AND status='queued'")->execute([$j['id']]);$pdo->prepare("INSERT INTO sms_events(job_id,event_type,detail,created_at) VALUES(?,'sent','Test mode simulation',NOW())")->execute([$j['id']]);}$pdo->exec('DELETE FROM api_rate_limits WHERE window_start < DATE_SUB(NOW(),INTERVAL 1 DAY)');$pdo->exec("UPDATE gateways SET status='offline' WHERE last_seen < DATE_SUB(NOW(),INTERVAL 3 MINUTE) AND status='online'");$pdo->exec("UPDATE campaigns SET status='completed',ended_at=NOW() WHERE status IN ('queued','running') AND NOT EXISTS (SELECT 1 FROM sms_jobs WHERE campaign_id=campaigns.id AND status IN ('queued','processing'))");echo 'simulated='.count($jobs).PHP_EOL;
